  4	/**
  5	 * A class representing the shared characteristics of plants
  6	 *
  7	 * @version 01.03.22
  8	 */
  9	
 10	public abstract class Plant extends Organism
 11	{
 12	    // whether it is raining or not
 13	    private boolean rain;
 14	
 15	    // A shared random number generator to control breeding.
 16	    private static final Random rand = Randomizer.getRandom();
 17	
 18	    /**
 19	     * Create a new plant at a location in field.
 20	     *
 21	     * @param field The field currently occupied.
 22	     * @param location The location within the field.
 23	     */
 24	    public Plant(Field field, Location location) {
 25	        super(field, location);
 26	        rain = false;
 27	    }
 28	
 29	    /**
 30	     * Make this plant act - that is: make it do
 31	     * whatever it wants/needs to do.
 32	     * @param newPlants A list to receive newly created plants.
 33	     */
 34	    abstract public void act(List<Plant> newPlants);
 35	
 36	    /**
 37	     * Create a new plant of the current species.
 38	     * @param field The field in which the plant will live.
 39	     * @param location The plant location.
 40	     * @return A new plant of the current species.
 41	     */
 42	    abstract protected Plant createYoung(Field field, Location location);
 43	
 44	    /**
 45	     * @return The probability that this plant reproduces in one step.
 46	     */
 47	    abstract protected double getReproducingProbability();
 48	
 49	    /**
 50	     * @return The maximum number of offspring this plant can produce.
 51	     */
 52	    abstract protected int getMaxOffspringSize();
 53	
 54	    /**
 55	     * assign true to rain
 56	     */
 57	    protected void setRain(){ rain = true; }
 58	
 59	    /**
 60	     * assign false to rain
 61	     */
 62	    protected void resetRain(){ rain = false; }
 63	
 64	    /**
 65	     * Generate a number representing the number of plants to produce,
 66	     * if it can reproduce.
 67	     * If it is raining, then the number of offspring is increased
 68	     * @return The number of offspring (may be zero).
 69	     */
 70	    protected int breed(double REPRODUCING_PROBABILITY, int MAX_OFFSPRING_SIZE)
 71	    {
 72	        int offspring = 0;
 73	        if (rand.nextDouble() <= (REPRODUCING_PROBABILITY)){
 74	            if (rain){
 75	                offspring = rand.nextInt(MAX_OFFSPRING_SIZE) + 3;
 76	            }
 77	            else {
 78	                offspring = rand.nextInt(MAX_OFFSPRING_SIZE);
 79	            }
 80	        }
 81	        return offspring;
 82	    }
 83	
 84	    /**
 85	     * Execute the common plant lifecycle for one simulation step.
 86	     * @param newPlants A list to receive newly created plants.
 87	     */
 88	    protected final void performAct(List<Plant> newPlants) {
 89	        if(isAlive()) {
 90	            grow(newPlants);
 91	        }
 92	    }
 93	
 94	    private void grow(List<Plant> newPlants) {
 95	        Field field = getField();
 96	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
 97	        int offspring = breed(getReproducingProbability(), getMaxOffspringSize());
 98	        for(int b = 0; b < offspring && free.size() > 0; b++) {
 99	            Location location = free.remove(0);
100	            Plant young = createYoung(field, location);
101	            newPlants.add(young);
102	        }
103	    }
104	}
